from pathlib import Path
import json,os,subprocess,time,sys
p=Path(__file__).resolve().parent;name=sys.argv[1];assert name in ['logical_nested_native','logical_activation_nested'];assert not(p/(name+'-RUN.json')).exists();a=json.loads((p/'BINARY.json').read_text());r=next(r for r in a['records'] if r['target']['name']==name);assert r['executable'];subprocess.run([sys.executable,str(p/'guard.py'),'before-'+name],check=True)
cmd=[r['executable'],'--nocapture','--test-threads=1'];tmp=p/'test-tmp';tmp.mkdir(exist_ok=True);row={'command':cmd,'cwd':str(p/'repo'),'TMPDIR':str(tmp),'target':name,'features':r['features'],'profile':r['profile'],'enumeratedTests':a['enumeratedTests'][name],'launch':True};(p/(name+'-RUN.json')).write_text(json.dumps(row,indent=2)+'\n');print(json.dumps({'launch':name,'tests':len(row['enumeratedTests'])}),flush=True);start=time.monotonic()
with (p/(name+'.log')).open('w') as out:rc=subprocess.run(cmd,cwd=p/'repo',env=dict(os.environ,TMPDIR=str(tmp)),stdout=out,stderr=subprocess.STDOUT).returncode
text=(p/(name+'.log')).read_text();row.update(exit=rc,seconds=round(time.monotonic()-start,2),summary=[l for l in text.splitlines() if l.startswith('test result:')]);(p/(name+'-RUN.json')).write_text(json.dumps(row,indent=2)+'\n');subprocess.run([sys.executable,str(p/'guard.py'),'after-'+name],check=True);print(json.dumps({'target':name,'exit':rc,'seconds':row['seconds'],'summary':row['summary']}),flush=True);sys.exit(rc)
